class WorkerTest(unittest.TestCase):
    def setUp(self):
        del CALLS[:]
        del m.DONE[:]

    def test_jobs_run(self):
        blob = m.encode_job("resize", {"path": "a.png", "width": 640, "height": 480})
        self.assertIsInstance(blob, bytes)
