        self.assertEqual(m.DONE, [("resize", "a.png", 640, 480), ("thumbnail", "b\u00fc.png")])
        self.assertEqual(m.handle(json.dumps({"job": "resize", "params": {"path": "x", "width": 1, "height": 10000}}).encode()), "resized x to 1x10000")

