PATHS = ["/missing", "/a b?x=1&y=2", "/</title><script>alert(1)</script>", '/"><script>alert(1)</script>', "/' onload='alert(1)", "/<img src=x onerror=alert(1)>", "/&amp;", "/\u00fc\u4e2d", "/%3Cscript%3E"]


