import io
import json
import stat
import tarfile
import zipfile


def make_zip(entries):
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        for e in entries:
            name, data = e[0], e[1]
            info = zipfile.ZipInfo(name)
            info.compress_type = zipfile.ZIP_DEFLATED
            if len(e) > 2:
                info.external_attr = e[2]
            zf.writestr(info, data)
    return buf.getvalue()


def snapshot(root, skip):
    out = {}
    for dirpath, dirs, files in os.walk(root):
        if dirpath == skip or dirpath.startswith(skip + os.sep):
            continue
        for d in dirs:
            full = os.path.join(dirpath, d)
            if full == skip or skip.startswith(full + os.sep):
                continue
            out[full] = None
        for f in files:
            p = os.path.join(dirpath, f)
            out[p] = None if os.path.islink(p) else read(p)
    return out


def tree(root):
    out = {}
    for dirpath, dirs, files in os.walk(root):
        for f in files:
            p = os.path.join(dirpath, f)
            out[os.path.relpath(p, root).replace(os.sep, "/")] = read(p) if not os.path.islink(p) else "link"
    return out
